const s = $input.first().json || {};

function fail(detail) {
  return [{
    json: {
      ...s,
      _parent_fail: {
        code: 'INTERNAL_CONTRACT_ERROR',
        stage: 'PARENT_ENTRY',
        detail
      },
      _parent_route: 'FAILED'
    }
  }];
}

if (!s || typeof s !== 'object' || Array.isArray(s)) {
  return fail('Parent input must be one canonical object.');
}

if (!s.airtable_record_id) return fail('Missing airtable_record_id.');
if (!s.run_id) return fail('Missing run_id.');
if (!s.email) return fail('Missing canonical email.');
if (!s.email_domain) return fail('Missing email_domain.');

if (s.enrichment_status !== 'processing') {
  return fail('Parent entry requires enrichment_status=processing.');
}
if (s.result_status !== 'pending') {
  return fail('Parent entry requires result_status=pending.');
}
if (s.manual_review !== false) {
  return fail('Parent entry requires manual_review=false.');
}
if (s.manual_review_reason !== null) {
  return fail('Parent entry requires manual_review_reason=null.');
}
if (s.routing_outcome !== null) {
  return fail('Parent entry requires routing_outcome=null.');
}

return [{
  json: {
    ...s,
    _parent: {
      contract_version: 'PARENT_CORE_THROUGH_2E_V1',
      started_at: new Date().toISOString(),
      stage: 'READY_FOR_2A'
    },
    _parent_route: 'CONTINUE'
  }
}];

const s = $input.first().json || {};

function internal(detail) {
  return [{
    json: {
      ...s,
      _parent_fail: {
        code: 'INTERNAL_CONTRACT_ERROR',
        stage: 'AFTER_2A',
        detail
      },
      _parent_route: 'FAILED'
    }
  }];
}

if (s.routing_outcome === 'FAILED' || s.enrichment_status === 'failed' || s.result_status === 'failed') {
  return [{ json: { ...s, _parent_route: 'FAILED' } }];
}

if (s.manual_review === true || s.routing_outcome === 'MANUAL_REVIEW') {
  return [{ json: { ...s, _parent_route: 'MANUAL_REVIEW' } }];
}

const happy =
  s.account_resolution_status === 'CONFIRMED' &&
  s.account_company &&
  s.manual_review === false &&
  s.manual_review_reason === null &&
  s.enrichment_status === 'processing' &&
  s.result_status === 'pending' &&
  s.routing_outcome === null;

if (happy) {
  return [{
    json: {
      ...s,
      _parent: { ...(s._parent || {}), stage: 'READY_FOR_2B' },
      _parent_route: 'CONTINUE'
    }
  }];
}

return internal('Unrecognized Layer 2A output/lifecycle tuple.');

const s = $input.first().json || {};

function internal(detail) {
  return [{
    json: {
      ...s,
      _parent_fail: {
        code: 'INTERNAL_CONTRACT_ERROR',
        stage: 'AFTER_2B',
        detail
      },
      _parent_route: 'FAILED'
    }
  }];
}

if (s.routing_outcome === 'FAILED' || s.enrichment_status === 'failed' || s.result_status === 'failed') {
  return [{ json: { ...s, _parent_route: 'FAILED' } }];
}

if (s.manual_review === true || s.routing_outcome === 'MANUAL_REVIEW') {
  return [{ json: { ...s, _parent_route: 'MANUAL_REVIEW' } }];
}

const allowed = new Set(['CONFIRMED', 'NOT_FOUND', 'SKIPPED_ROLE_INBOX']);
if (
  allowed.has(s.person_resolution_status) &&
  s.manual_review === false &&
  s.manual_review_reason === null &&
  s.enrichment_status === 'processing' &&
  s.result_status === 'pending' &&
  s.routing_outcome === null
) {
  return [{
    json: {
      ...s,
      _parent: { ...(s._parent || {}), stage: 'READY_FOR_2C' },
      _parent_route: 'CONTINUE'
    }
  }];
}

return internal('Unrecognized Layer 2B output/lifecycle tuple.');

const s = $input.first().json || {};

function internal(detail) {
  return [{
    json: {
      ...s,
      _parent_fail: {
        code: 'INTERNAL_CONTRACT_ERROR',
        stage: 'AFTER_2C',
        detail
      },
      _parent_route: 'FAILED'
    }
  }];
}

if (s.routing_outcome === 'FAILED' || s.enrichment_status === 'failed' || s.result_status === 'failed') {
  return [{ json: { ...s, _parent_route: 'FAILED' } }];
}

if (s.manual_review === true || s.routing_outcome === 'MANUAL_REVIEW') {
  return [{ json: { ...s, _parent_route: 'MANUAL_REVIEW' } }];
}

const lifecycleOpen =
  s.manual_review === false &&
  s.manual_review_reason === null &&
  s.enrichment_status === 'processing' &&
  s.result_status === 'pending' &&
  s.routing_outcome === null;

if (!lifecycleOpen) {
  return internal('Layer 2C returned a non-terminal state with an invalid lifecycle tuple.');
}

const ev = s.inbound_employer_verification || {};

const accountOnly =
  (s.person_resolution_status === 'NOT_FOUND' || s.person_resolution_status === 'SKIPPED_ROLE_INBOX') &&
  s.person === null &&
  s.matched_employer_candidate === null &&
  ev.status === 'SKIPPED' &&
  s.matched_employer === null &&
  (s.organization_relationship === null || s.organization_relationship === undefined);

if (accountOnly) {
  return [{
    json: {
      ...s,
      _parent: { ...(s._parent || {}), stage: 'READY_FOR_2E_ACCOUNT_ONLY' },
      _parent_route: 'ACCOUNT_ONLY_2E'
    }
  }];
}

const verified =
  s.person_resolution_status === 'CONFIRMED' &&
  !!s.person &&
  ev.status === 'VERIFIED' &&
  !!s.matched_employer;

if (verified) {
  return [{
    json: {
      ...s,
      _parent: { ...(s._parent || {}), stage: 'READY_FOR_2D' },
      _parent_route: 'VERIFIED_TO_2D'
    }
  }];
}

return internal('Layer 2C output is neither canonical SKIPPED account-only nor VERIFIED person path.');

const s = $input.first().json || {};

function internal(detail) {
  return [{
    json: {
      ...s,
      _parent_fail: {
        code: 'INTERNAL_CONTRACT_ERROR',
        stage: 'AFTER_2D',
        detail
      },
      _parent_route: 'FAILED'
    }
  }];
}

if (s.routing_outcome === 'FAILED' || s.enrichment_status === 'failed' || s.result_status === 'failed') {
  return [{ json: { ...s, _parent_route: 'FAILED' } }];
}

if (
  s.manual_review === true ||
  s.routing_outcome === 'MANUAL_REVIEW' ||
  s.organization_relationship === 'UNKNOWN' ||
  s.organization_relationship === 'UNRELATED'
) {
  return [{ json: { ...s, _parent_route: 'MANUAL_REVIEW' } }];
}

const positive = new Set([
  'SAME_ENTITY',
  'SUBSIDIARY',
  'PARENT',
  'BRAND_OR_BUSINESS_UNIT'
]);

const happy =
  positive.has(s.organization_relationship) &&
  s.manual_review === false &&
  s.manual_review_reason === null &&
  s.enrichment_status === 'processing' &&
  s.result_status === 'pending' &&
  s.routing_outcome === null;

if (happy) {
  return [{
    json: {
      ...s,
      _parent: { ...(s._parent || {}), stage: 'READY_FOR_2E_VERIFIED_PERSON' },
      _parent_route: 'VERIFIED_PERSON_2E'
    }
  }];
}

return internal('Unrecognized Layer 2D output/lifecycle tuple.');

const s = $input.first().json || {};

const mode =
  (s.l2e_config && s.l2e_config.classifier_execution_mode) ||
  $vars.L2E_CLASSIFIER_EXECUTION_MODE;

const hydration =
  (s.l2e_config && s.l2e_config.hydration_endpoint_identity) ||
  $vars.L2E_HYDRATION_ENDPOINT_IDENTITY;

const profile =
  (s.l2e_config && s.l2e_config.profile_endpoint_identity) ||
  $vars.L2E_PROFILE_ENDPOINT_IDENTITY;

const title =
  (s.l2e_config && s.l2e_config.title_endpoint_identity) ||
  $vars.L2E_TITLE_ENDPOINT_IDENTITY ||
  null;

if (!mode || !hydration || !profile) {
  return [{
    json: {
      ...s,
      _parent_fail: {
        code: 'INTERNAL_CONTRACT_ERROR',
        stage: 'PREPARE_2E_ACCOUNT_ONLY',
        detail: 'Missing L2E runtime config variables.'
      },
      _parent_route: 'FAILED'
    }
  }];
}

return [{
  json: {
    ...s,
    _2e_entry_mode: 'ACCOUNT_ONLY',
    l2e_config: {
      ...(s.l2e_config || {}),
      classifier_execution_mode: mode,
      hydration_endpoint_identity: hydration,
      profile_endpoint_identity: profile,
      title_endpoint_identity: title
    },
    _parent: { ...(s._parent || {}), stage: 'EXECUTING_2E_ACCOUNT_ONLY' }
  }
}];

const s = $input.first().json || {};

const mode =
  (s.l2e_config && s.l2e_config.classifier_execution_mode) ||
  $vars.L2E_CLASSIFIER_EXECUTION_MODE;

const hydration =
  (s.l2e_config && s.l2e_config.hydration_endpoint_identity) ||
  $vars.L2E_HYDRATION_ENDPOINT_IDENTITY;

const profile =
  (s.l2e_config && s.l2e_config.profile_endpoint_identity) ||
  $vars.L2E_PROFILE_ENDPOINT_IDENTITY;

const title =
  (s.l2e_config && s.l2e_config.title_endpoint_identity) ||
  $vars.L2E_TITLE_ENDPOINT_IDENTITY ||
  null;

if (!mode || !hydration || !profile) {
  return [{
    json: {
      ...s,
      _parent_fail: {
        code: 'INTERNAL_CONTRACT_ERROR',
        stage: 'PREPARE_2E_VERIFIED_PERSON',
        detail: 'Missing L2E runtime config variables.'
      },
      _parent_route: 'FAILED'
    }
  }];
}

return [{
  json: {
    ...s,
    _2e_entry_mode: 'VERIFIED_PERSON',
    l2e_config: {
      ...(s.l2e_config || {}),
      classifier_execution_mode: mode,
      hydration_endpoint_identity: hydration,
      profile_endpoint_identity: profile,
      title_endpoint_identity: title
    },
    _parent: { ...(s._parent || {}), stage: 'EXECUTING_2E_VERIFIED_PERSON' }
  }
}];

const s = $input.first().json || {};

function internal(detail) {
  return [{
    json: {
      ...s,
      _parent_fail: {
        code: 'INTERNAL_CONTRACT_ERROR',
        stage: 'AFTER_2E',
        detail
      },
      _parent_route: 'FAILED'
    }
  }];
}

if (s._2e_fail) {
  return internal(
    'Layer 2E returned INTERNAL_CONTRACT_ERROR: ' +
    String(s._2e_fail.detail || s._2e_fail.code || 'unknown')
  );
}

if (s.routing_outcome === 'FAILED' || s.enrichment_status === 'failed' || s.result_status === 'failed') {
  return [{ json: { ...s, _parent_route: 'FAILED' } }];
}

if (!['success', 'empty', 'failed'].includes(s.hr_discovery_status)) {
  return internal('Missing or invalid hr_discovery_status.');
}

if (!Array.isArray(s.hr_contacts)) {
  return internal('hr_contacts must be an array.');
}
if (!Array.isArray(s.flagged_hr_contacts)) {
  return internal('flagged_hr_contacts must be an array.');
}
if (!s.hr_discovery_evidence || typeof s.hr_discovery_evidence !== 'object') {
  return internal('Missing hr_discovery_evidence.');
}

if (
  s.manual_review !== false ||
  s.manual_review_reason !== null ||
  s.enrichment_status !== 'processing' ||
  s.result_status !== 'pending' ||
  s.routing_outcome !== null
) {
  return internal('Layer 2E normal output mutated upstream open lifecycle.');
}

return [{
  json: {
    ...s,
    _parent: {
      ...(s._parent || {}),
      stage: 'CORE_THROUGH_2E_COMPLETE',
      completed_through: '2E'
    },
    _parent_route: 'CORE_COMPLETE'
  }
}];

const s = $input.first().json || {};
return [{
  json: {
    ...s,
    _parent_core_result: {
      status: 'CORE_THROUGH_2E_COMPLETE',
      next_layer: 'NOT_IMPLEMENTED_YET',
      note: 'Account Fit / Persona Fit / Data Confidence / Sales Brief / Final Routing are intentionally not part of this parent version.'
    }
  }
}];

const s = $input.first().json || {};
return [{
  json: {
    ...s,
    _parent_terminal: {
      type: 'MANUAL_REVIEW',
      persistence_wired: false,
      note: 'TEST/ASSEMBLY parent: terminal Airtable persistence is not wired yet.'
    }
  }
}];

const s = $input.first().json || {};
return [{
  json: {
    ...s,
    _parent_terminal: {
      type: 'FAILED',
      persistence_wired: false,
      note: 'TEST/ASSEMBLY parent: terminal Airtable persistence is not wired yet.'
    }
  }
}];

const s = $input.first().json || {};
const company = s.account_company || {};

const rawCountry = company.country == null
  ? null
  : String(company.country).trim();

const employeeCount =
  Number.isFinite(Number(company.employee_count))
    ? Number(company.employee_count)
    : null;

const TARGET_COUNTRIES = new Set([
  // US
  'united states', 'united states of america', 'usa', 'us',

  // Israel
  'israel', 'il',

  // UK
  'united kingdom', 'uk', 'great britain', 'gb',

  // Switzerland / Norway
  'switzerland', 'ch',
  'norway', 'no',

  // EU
  'austria', 'at',
  'belgium', 'be',
  'bulgaria', 'bg',
  'croatia', 'hr',
  'cyprus', 'cy',
  'czech republic', 'czechia', 'cz',
  'denmark', 'dk',
  'estonia', 'ee',
  'finland', 'fi',
  'france', 'fr',
  'germany', 'de',
  'greece', 'gr',
  'hungary', 'hu',
  'ireland', 'ie',
  'italy', 'it',
  'latvia', 'lv',
  'lithuania', 'lt',
  'luxembourg', 'lu',
  'malta', 'mt',
  'netherlands', 'nl',
  'poland', 'pl',
  'portugal', 'pt',
  'romania', 'ro',
  'slovakia', 'sk',
  'slovenia', 'si',
  'spain', 'es',
  'sweden', 'se'
]);

const country =
  rawCountry === null || rawCountry === ''
    ? null
    : rawCountry.toLowerCase();

const countryKnown = country !== null;
const employeeCountKnown =
  employeeCount !== null &&
  Number.isFinite(employeeCount) &&
  employeeCount >= 0;

const isTargetMarket =
  countryKnown ? TARGET_COUNTRIES.has(country) : null;

const reasons = [];

if (countryKnown) {
  reasons.push(
    isTargetMarket ? 'TARGET_MARKET' : 'NON_TARGET_MARKET'
  );
} else {
  reasons.push('COUNTRY_UNKNOWN');
}

if (!employeeCountKnown) {
  reasons.push('EMPLOYEE_COUNT_UNKNOWN');
} else if (employeeCount < 100) {
  reasons.push('EMPLOYEE_COUNT_BELOW_100');
} else if (employeeCount < 500) {
  reasons.push('EMPLOYEE_COUNT_100_499');
} else {
  reasons.push('EMPLOYEE_COUNT_500_PLUS');
}


// Exact precedence — first matching rule wins.

let accountFit;

if (countryKnown && !isTargetMarket) {
  accountFit = 'LOW';
}
else if (employeeCountKnown && employeeCount < 100) {
  accountFit = 'LOW';
}
else if (!countryKnown || !employeeCountKnown) {
  accountFit = 'UNKNOWN';
}
else if (isTargetMarket && employeeCount < 500) {
  accountFit = 'MEDIUM';
}
else if (isTargetMarket && employeeCount >= 500) {
  accountFit = 'HIGH';
}
else {
  accountFit = 'UNKNOWN';
}

return [{
  json: {
    ...s,

    account_fit: accountFit,
    account_fit_reasons: reasons,

    account_fit_evidence: {
      country: rawCountry,
      employee_count: employeeCountKnown
        ? employeeCount
        : null,
      target_market: isTargetMarket
    }
  }
}];

const s = $input.first().json || {};

const person = s.person || null;

const canonicalTitle =
  person &&
  typeof person.current_title === 'string' &&
  person.current_title.trim()
    ? person.current_title.trim()
    : null;

// ---------- Title normalization ----------

function normalizeTitle(value) {
  if (!value) return null;

  let x = String(value)
    .normalize('NFKC')
    .toLowerCase();

  x = x.replace(/\p{P}/gu, ' ');
  x = x.replace(/\s+/g, ' ').trim();

  return x || null;
}

function tokens(value) {
  return value ? value.split(' ') : [];
}

function containsPhrase(tokenList, phrase) {
  const p = phrase.split(' ');

  for (let i = 0; i <= tokenList.length - p.length; i++) {
    let match = true;

    for (let j = 0; j < p.length; j++) {
      if (tokenList[i + j] !== p[j]) {
        match = false;
        break;
      }
    }

    if (match) return true;
  }

  return false;
}


// ---------- Function classification ----------

const FUNCTION_PRECEDENCE = [
  'RECRUITING_OPERATIONS',
  'TALENT_ACQUISITION',
  'RECRUITING',
  'PEOPLE',
  'HR',
  'GENERAL_MANAGEMENT',
  'OTHER'
];

const FUNCTION_PHRASES = {
  RECRUITING_OPERATIONS: [
    'recruiting operations',
    'recruitment operations',
    'talent acquisition operations',
    'ta operations',
    'recruiting program',
    'recruiting programs',
    'recruitment program',
    'recruitment programs'
  ],

  TALENT_ACQUISITION: [
    'talent acquisition',
    'talent sourcing',
    'talent partner',
    'talent recruiter',
    'talent recruiting'
  ],

  PEOPLE: [
    'people operations',
    'people ops',
    'people partner',
    'people and culture',
    'people culture',
    'employee experience',
    'talent management',
    'talent development',
    'people analytics',
    'chief people officer',
    'chief talent officer'
  ],

  HR: [
    'human resources',
    'human resource',
    'human resources business partner',
    'hr business partner',
    'employee relations'
  ],

  GENERAL_MANAGEMENT: [
    'chief executive officer',
    'chief operating officer',
    'managing director',
    'general manager',
    'co founder'
  ]
};

const FUNCTION_TOKENS = {
  TALENT_ACQUISITION: [
    'sourcer'
  ],

  RECRUITING: [
    'recruiter',
    'recruiting',
    'recruitment',
    'staffing',
    'headhunter',
    'headhunting'
  ],

  PEOPLE: [
    'people'
  ],

  HR: [
    'hr',
    'hrbp',
    'hris'
  ],

  GENERAL_MANAGEMENT: [
    'founder',
    'cofounder',
    'ceo',
    'coo',
    'president'
  ],

  OTHER: [
    'sales',
    'marketing',
    'finance',
    'financial',
    'accounting',
    'engineering',
    'engineer',
    'software',
    'product',
    'legal',
    'counsel',
    'design',
    'data',
    'security',
    'customer',
    'support',
    'service',
    'medical',
    'clinical',
    'procurement',
    'logistics',
    'supply',
    'research',
    'operations'
  ]
};


// ---------- Seniority classification ----------

const SENIORITY_PRECEDENCE = [
  'EXECUTIVE',
  'HEAD_DIRECTOR',
  'MANAGER_LEAD',
  'SENIOR',
  'JUNIOR'
];

const SENIORITY_PHRASES = {
  EXECUTIVE: [
    'chief executive officer',
    'chief operating officer',
    'chief people officer',
    'chief talent officer',
    'chief human resources officer',
    'vice president',
    'managing director',
    'co founder'
  ],

  MANAGER_LEAD: [
    'team lead'
  ]
};

const SENIORITY_TOKENS = {
  EXECUTIVE: [
    'chief',
    'vp',
    'svp',
    'evp',
    'ceo',
    'coo',
    'cpo',
    'chro',
    'president',
    'founder',
    'cofounder'
  ],

  HEAD_DIRECTOR: [
    'head',
    'director'
  ],

  MANAGER_LEAD: [
    'manager',
    'lead'
  ],

  SENIOR: [
    'senior',
    'principal',
    'staff'
  ],

  JUNIOR: [
    'junior',
    'assistant',
    'intern',
    'trainee',
    'coordinator',
    'associate'
  ]
};


// ---------- Semantic classifier ----------

function classifyTitle(rawTitle) {
  const normalized = normalizeTitle(rawTitle);
  if (!normalized) {
    return {
      function: 'UNKNOWN',
      seniority: 'UNKNOWN',
      normalized_title: null,
      reason: 'EMPTY_TITLE'
    };
  }

  const tk = tokens(normalized);

  const functionMatches = new Set();

  for (const fn of FUNCTION_PRECEDENCE) {
    for (const phrase of FUNCTION_PHRASES[fn] || []) {
      if (containsPhrase(tk, phrase)) {
        functionMatches.add(fn);
      }
    }

    for (const token of FUNCTION_TOKENS[fn] || []) {
      if (tk.includes(token)) {
        functionMatches.add(fn);
      }
    }
  }

  const personaFunction =
    FUNCTION_PRECEDENCE.find(fn => functionMatches.has(fn))
    || 'UNKNOWN';


  const seniorityMatches = new Set();

  for (const level of SENIORITY_PRECEDENCE) {
    for (const phrase of SENIORITY_PHRASES[level] || []) {
      if (containsPhrase(tk, phrase)) {
        seniorityMatches.add(level);
      }
    }

    for (const token of SENIORITY_TOKENS[level] || []) {
      if (tk.includes(token)) {
        seniorityMatches.add(level);
      }
    }
  }

  let personaSeniority =
    SENIORITY_PRECEDENCE.find(level => seniorityMatches.has(level))
    || null;

  if (!personaSeniority) {
    personaSeniority =
      personaFunction === 'UNKNOWN'
        ? 'UNKNOWN'
        : 'INDIVIDUAL_CONTRIBUTOR';
  }

  return {
    function: personaFunction,
    seniority: personaSeniority,
    normalized_title: normalized,
    reason:
      personaFunction === 'UNKNOWN'
        ? 'NO_SUPPORTED_FUNCTION_CUE'
        : 'FUNCTION_CLASSIFIED'
  };
}


// ---------- Persona Fit ----------

// ---------- Persona Fit ----------

const HR_FAMILY = new Set([
  'RECRUITING_OPERATIONS',
  'TALENT_ACQUISITION',
  'RECRUITING',
  'PEOPLE',
  'HR'
]);

const VERIFIED_RELATIONSHIPS = new Set([
  'SAME_ENTITY',
  'SUBSIDIARY',
  'PARENT',
  'BRAND_OR_BUSINESS_UNIT'
]);

function cleanTitle(value) {
  if (typeof value !== 'string') return null;

  const v = value.trim();
  return v || null;
}

let title = canonicalTitle;

let titleSource =
  title
    ? 'CANONICAL_CURRENT_TITLE'
    : null;

let titlesConsidered =
  title
    ? [title]
    : [];

const canUseClassificationFallback =
  person != null &&
  s.person_resolution_status === 'CONFIRMED' &&
  s.inbound_employer_verification?.status === 'VERIFIED' &&
  VERIFIED_RELATIONSHIPS.has(s.organization_relationship);


// --------------------------------------------------
// A. Verified current target-account roles
// --------------------------------------------------

let verifiedTargetTitlesFound = false;

if (!title && canUseClassificationFallback) {

  const roles =
    Array.isArray(
      s.inbound_employer_verification?.current_roles_considered
    )
      ? s.inbound_employer_verification.current_roles_considered
      : [];

  const verifiedCurrentTitles = [
    ...new Set(
      roles
        .filter(role =>
          role?.role_observation?.currentness === 'CURRENT' &&
          role?.account_comparison?.result === 'IDENTITY_MATCH' &&
          role?.selection_eligibility === 'ELIGIBLE_CURRENT'
        )
        .map(role =>
          cleanTitle(role?.role_observation?.title)
        )
        .filter(Boolean)
    )
  ];

  if (verifiedCurrentTitles.length > 0) {

    verifiedTargetTitlesFound = true;
    titlesConsidered = verifiedCurrentTitles;

    const classifiedRoles =
      verifiedCurrentTitles.map(roleTitle => ({
        title: roleTitle,
        classification: classifyTitle(roleTitle)
      }));

    const hrRoles =
      classifiedRoles.filter(x =>
        HR_FAMILY.has(x.classification.function)
      );

    const explicitNonHrRoles =
      classifiedRoles.filter(x =>
        x.classification.function !== 'UNKNOWN' &&
        !HR_FAMILY.has(x.classification.function)
      );

    // Safe consensus:
    // at least one verified HR-family title
    // and no verified current title explicitly contradicts it.
    if (
      hrRoles.length > 0 &&
      explicitNonHrRoles.length === 0
    ) {

      const functionRank =
        new Map(
          FUNCTION_PRECEDENCE.map(
            (value, index) => [value, index]
          )
        );

      const seniorityRank =
        new Map(
          [
            ...SENIORITY_PRECEDENCE,
            'INDIVIDUAL_CONTRIBUTOR',
            'UNKNOWN'
          ].map(
            (value, index) => [value, index]
          )
        );

      hrRoles.sort((a, b) => {
        const functionDiff =
          (functionRank.get(a.classification.function) ?? 999) -
          (functionRank.get(b.classification.function) ?? 999);

        if (functionDiff !== 0) {
          return functionDiff;
        }

        return (
          (seniorityRank.get(a.classification.seniority) ?? 999) -
          (seniorityRank.get(b.classification.seniority) ?? 999)
        );
      });

      title = hrRoles[0].title;

      titleSource =
        verifiedCurrentTitles.length > 1
          ? 'VERIFIED_CURRENT_ROLE_CONSENSUS'
          : 'VERIFIED_CURRENT_ROLE';
    }
  }
