// ============================================================
// 2. UTF-8
// Same implementation profile as frozen SI v4.7
// ============================================================

function utf8Bytes(str) {
  const out = [];

  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);

    if (c < 0x80) {
      out.push(c);
    }

    else if (c < 0x800) {
      out.push(
        0xC0 | (c >> 6),
        0x80 | (c & 63)
      );
    }

    else if (
      c >= 0xD800 &&
      c <= 0xDBFF &&
      i + 1 < str.length
    ) {
      const c2 = str.charCodeAt(i + 1);

      if (c2 >= 0xDC00 && c2 <= 0xDFFF) {
        const cp =
          0x10000 +
          ((c - 0xD800) << 10) +
          (c2 - 0xDC00);

        out.push(
          0xF0 | (cp >> 18),
          0x80 | ((cp >> 12) & 63),
          0x80 | ((cp >> 6) & 63),
          0x80 | (cp & 63)
        );

        i++;
      } else {
        out.push(0xEF, 0xBF, 0xBD);
      }
    }

    else if (c >= 0xDC00 && c <= 0xDFFF) {
      out.push(0xEF, 0xBF, 0xBD);
    }

    else {
      out.push(
        0xE0 | (c >> 12),
        0x80 | ((c >> 6) & 63),
        0x80 | (c & 63)
      );
    }
  }

  return out;
}


