      const S0 =
        ((a >>> 2) | (a << 30)) ^
        ((a >>> 13) | (a << 19)) ^
        ((a >>> 22) | (a << 10));

      const maj =
        (a & b) ^
        (a & c) ^
        (b & c);

      const t2 =
        (S0 + maj) | 0;

      h = g;
      g = f;
      f = e;
      e = (d + t1) | 0;
      d = c;
      c = b;
      b = a;
      a = (t1 + t2) | 0;
    }

    H[0] = (H[0] + a) | 0;
    H[1] = (H[1] + b) | 0;
    H[2] = (H[2] + c) | 0;
    H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0;
    H[5] = (H[5] + f) | 0;
    H[6] = (H[6] + g) | 0;
    H[7] = (H[7] + h) | 0;
  }

  let hex = '';

  for (let i = 0; i < 8; i++) {
    const v = H[i] >>> 0;

    hex +=
      ('00000000' + v.toString(16))
        .slice(-8);
  }

  return hex;
}


// ============================================================
// 4. JCS canonicalization
// Same closed-JSON implementation used by SI
// ============================================================

function jcs(v) {

  if (v === null) {
    return 'null';
  }

  const t = typeof v;

  if (t === 'boolean') {
    return v ? 'true' : 'false';
  }

  if (t === 'number') {

    if (!isFinite(v)) {
      throw new Error('JCS_NON_FINITE_NUMBER');
    }

    if (
      Math.floor(v) === v &&
      Math.abs(v) < 1e21
    ) {
      return String(v);
    }

    return JSON.stringify(v);
  }

  if (t === 'string') {
    return JSON.stringify(v);
  }

  if (Array.isArray(v)) {
    return (
      '[' +
      v.map(jcs).join(',') +
      ']'
    );
  }

  if (t === 'object') {

    const keys =
      Object.keys(v)
        .sort((a, b) => {

          const n =
            Math.min(a.length, b.length);

          for (let i = 0; i < n; i++) {

            const x = a.charCodeAt(i);
            const y = b.charCodeAt(i);

            if (x !== y) {
              return x < y ? -1 : 1;
            }
          }

          if (a.length === b.length) {
            return 0;
          }

          return a.length < b.length
            ? -1
            : 1;
        });

    const parts = [];

    for (const key of keys) {

      if (v[key] === undefined) {
        continue;
      }

      parts.push(
        JSON.stringify(key) +
        ':' +
        jcs(v[key])
      );
    }

    return (
      '{' +
      parts.join(',') +
      '}'
    );
  }

  throw new Error(
    'JCS_UNSUPPORTED_TYPE:' + t
  );
}


