  Array.isArray(brief.sales_hypotheses)
    ? brief.sales_hypotheses
    : [];

// Signals that generated a sales hypothesis.
const hypothesisSignalIds = new Set(
  hypotheses
    .map(h => h?.signal_id)
    .filter(Boolean)
);

// Supplement canonical current_context with useful company events.
//
// Exclude:
// - inconsistent signals
// - explicit target conflicts
//
// Keep:
// - product / market launches
// - expansion
// - funding
// - partnerships / acquisitions
// - recruiting expansion
// - hiring
const usefulResearchSignals = researchEvidence
  .filter(signal =>
    signal &&
    signal.classification_status === "CONSISTENT" &&
    signal.target_binding !== "CONFLICT" &&
    [
      "PRODUCT_OR_MARKET_LAUNCH",
      "COMPANY_EXPANSION",
      "FUNDING_OR_INVESTMENT",
      "PARTNERSHIP_OR_ACQUISITION",
      "RECRUITING_EXPANSION",
      "HIRING_SIGNAL"
    ].includes(signal.signal_type)
  )
  .map(signal => ({
    ...signal,

    // research_evidence may not carry canonical freshness
    evidence_freshness:
      signal.evidence_freshness || null
  }));

// ============================================================
// 3. Merge + deduplicate signals
// ============================================================

const seenSignals = new Set();

const mergedSignals = [
  ...currentSignals,
  ...usefulResearchSignals
].filter(signal => {
  const key = [
    signal?.signal_type || "",
    signal?.source_url || "",
    signal?.evidence_excerpt || ""
  ].join("|");

  if (seenSignals.has(key)) {
    return false;
  }

  seenSignals.add(key);
  return true;
});

// Mark signals that came from canonical current_context.
const currentSignalKeys = new Set(
  currentSignals.map(signal =>
    [
      signal?.signal_type || "",
      signal?.source_url || "",
      signal?.evidence_excerpt || ""
    ].join("|")
  )
);

// Ranking:
//
// 1. Signal that generated a sales hypothesis
// 2. Canonical current_context
// 3. First-party research evidence
// 4. Remaining useful research evidence
//
// Limit UI to three signals.
const signals = [...mergedSignals]
  .sort((a, b) => {
    const aHypothesis =
      hypothesisSignalIds.has(a?.signal_id) ? 1 : 0;

    const bHypothesis =
      hypothesisSignalIds.has(b?.signal_id) ? 1 : 0;

    if (aHypothesis !== bHypothesis) {
      return bHypothesis - aHypothesis;
    }

    const aKey = [
      a?.signal_type || "",
      a?.source_url || "",
      a?.evidence_excerpt || ""
    ].join("|");

    const bKey = [
      b?.signal_type || "",
      b?.source_url || "",
      b?.evidence_excerpt || ""
    ].join("|");

    const aCurrent =
      currentSignalKeys.has(aKey) ? 1 : 0;

    const bCurrent =
      currentSignalKeys.has(bKey) ? 1 : 0;

    if (aCurrent !== bCurrent) {
      return bCurrent - aCurrent;
    }
    const aFirstParty =
      a?.source_type === "FIRST_PARTY" ? 1 : 0;

    const bFirstParty =
      b?.source_type === "FIRST_PARTY" ? 1 : 0;

    return bFirstParty - aFirstParty;
  })
  .slice(0, 3);

