      "Medium account fit · Strong persona fit",

    LOW_ACCOUNT_FIT:
      "Low account fit",

    PERSONA_UNKNOWN:
      "Persona could not be confidently classified"
  };

  return overrides[value] || humanizeEnum(value);
}
// Clean noisy scraped evidence for Softr.
//
// Canonical Sales Intelligence evidence remains untouched.
function cleanSignalText(value) {
  if (!value) return null;

  let text = String(value)
    .replace(/\s+/g, " ")
    .trim();

  if (!text) return null;

  // Careers pages sometimes return navigation and vacancy-list noise.
  if (/explore our open roles/i.test(text)) {
    return "Explore our open roles.";
  }

  // Keep the Softr cards compact.
  const MAX_LENGTH = 220;

  if (text.length > MAX_LENGTH) {
    const shortened = text
      .slice(0, MAX_LENGTH - 3)
      .replace(/\s+\S*$/, "")
      .trim();

    return `${shortened}...`;
  }

  return text;
}

// Canonical rendered_text contains:
//
// Source-attributed context
// Potential relevance
// Generic caveat
//
// Softr only needs the actual sales angle.
function extractPotentialRelevance(value) {
  if (!value) return null;

  const text = String(value).trim();

  if (!text) return null;

  const match = text.match(
    /Potential relevance:\s*([\s\S]*?)(?:\n\s*\nThis may be relevant|\s*$)/i
  );

  if (match?.[1]) {
    return match[1].trim();
  }

  // Safe fallback if SI wording changes later.
  return text;
}

